Extract Cyrillic string literals from OnePit C# files — mkdir -p multicode/.cache/argon-strings && cat > multicode/.cache/argon-strings/extract.py <<'EOF'
import sys, os, re, json
ROOT = sys.argv[1]
CYR = re.compile('[Ѐ-ӿ]')
out = []
def scan(path):
    src = open(path, encoding='utf-8', errors='replace').read()
    i = 0; n = len(src); line = 1
    res = []
    while i < n:
        c = src[i]
        if c == '\n': line += 1; i += 1; continue
        # comments
        if src.startswith('//', i):
            j = src.find('\n', i); j = n if j < 0 else j
            i = j; continue
        if src.startswith('/*', i):
            j = src.find('*/', i+2); j = n if j < 0 else j+2
            line += src.count('\n', i, j); i = j; continue
        # char literal
        if c == "'":
            j = i+1
            while j < n and src[j] != "'":
                if src[j] == '\\': j += 1
                j += 1
            i = j+1; continue
        verb = False; interp = False; start_line = line
        prefix_len = 0
        if c in '@$':
            # handle @$" or $@" or @" or $"
            k = i; flags = ''
            while k < n and src[k] in '@$' and len(flags) < 2:
                flags += src[k]; k += 1
            if k < n and src[k] == '"' and flags and not (i>0 and (src[i-1].isalnum() or src[i-1]=='_')):
                verb = '@' in flags; interp = '$' in flags
                i = k; c = '"'
            else:
                i += 1; continue
        if c == '"':
            j = i+1; buf = []
            if verb:
                while j < n:
                    if src[j] == '"':
                        if j+1 < n and src[j+1] == '"': buf.append('"'); j += 2; continue
                        break
                    if src[j] == '\n': line += 1
                    buf.append(src[j]); j += 1
            else:
                while j < n and src[j] != '"' and src[j] != '\n':
                    if src[j] == '\\' and j+1 < n:
                        buf.append(src[j:j+2]); j += 2; continue
                    buf.append(src[j]); j += 1
            text = ''.join(buf)
            if CYR.search(text):
                res.append((start_line, text, verb, interp))
            i = j+1; continue
        i += 1
    return res
files = []
for dp, dn, fn in os.walk(ROOT):
    for f in fn:
        if f.endswith('.cs'): files.append(os.path.join(dp, f))
files.sort()
for f in files:
    rel = os.path.relpath(f, ROOT)
    for ln, text, verb, interp in scan(f):
        out.append({'file': rel, 'line': ln, 'text': text, 'verbatim': verb, 'interp': interp})
json.dump(out, sys.stdout, ensure_ascii=False, indent=0)
